patch.content:
body {
  background-color: #ffffff;
  color: #18181b;
  font-family: system-ui, "Segoe UI", sans-serif;
  line-height: 1.6;
  padding: 16px;
}

.skip {
  position: absolute;
  left: -9999px;
}

.skip:focus {
  left: 8px;
  top: 8px;
  background-color: #18181b;
  color: #ffffff;
  padding: 8px 12px;
  border-radius: 6px;
}

.topbar {
  display: flex;
  align-items: center;
  gap: 12px;
  padding-bottom: 12px;
  border-bottom: 1px solid #e4e4e7;
}

.logo {
  font-weight: 700;
  font-size: 20px;
  color: #18181b;
  text-decoration: none;
  margin-right: auto;
}

.icon-btn {
  background: none;
  border: 1px solid #d4d4d8;
  border-radius: 8px;
  padding: 6px 10px;
  font-size: 16px;
  cursor: pointer;
}

.cart-count {
  margin-left: 4px;
  font-weight: 700;
}

.divider {
  width: 100%;
  height: 8px;
}

h1 { font-size: 28px; }

.product-card img {
  width: 100%;
  max-width: 320px;
  aspect-ratio: 4 / 3;
  object-fit: cover;
  border-radius: 10px;
}

/* энд бичнэ үү */

.price {
  color: #a9a9a9;
  font-size: 18px;
}

.stock {
  color: #f87171;
  font-weight: 600;
}

.muted { color: #b4b4bb; }

.btn-add {
  display: inline-block;
  background-color: #1d4ed8;
  color: #ffffff;
  padding: 10px 16px;
  border: none;
  border-radius: 6px;
  cursor: pointer;
  font-size: 15px;
  font-family: inherit;
}

.order-form {
  display: grid;
  gap: 8px;
  max-width: 320px;
  margin-top: 24px;
}

.order-form input {
  padding: 10px 12px;
  border: 1px solid #d4d4d8;
  border-radius: 8px;
  font-size: 16px;
}

.field-error,
.form-error {
  color: #b91c1c;
  font-size: 14px;
  margin: 0;
}

// Сагсны тоолуурыг шинэчилнэ. Энэ файлыг өөрчлөх шаардлагагүй.

let count = 0;

function addToCart() {
  count += 1;
  document.querySelector('[data-testid="cart-count"]').textContent = String(count);
}

document.querySelector('[data-testid="add"]').addEventListener("click", addToCart);

